function minimumBoxes(n) {
  let size = 0;
  let used = 0;

  while (used + (size + 1) * (size + 2) / 2 <= n) {
    size++;
    used += size * (size + 1) / 2;
  }

  const floor = size * (size + 1) / 2;
  let extra = 0;
  while (used < n) {
    extra++;
    used += extra;
  }
  return floor + extra;
}

