function minimumBoxes(n) {
  // Lay f floor boxes diagonal by diagonal from a corner, then stack level by level using the rule itself.
  const fits = (f) => {
    let level = [];
    for (let d = 0; level.length < f; d++)
      for (let x = 0; x <= d && level.length < f; x++) level.push([x, d - x]);
    let total = 0;
    for (let z = 0; level.length > 0 && z < n; z++) {
      total += level.length;
      if (total >= n) return true;
      const here = new Set(level.map(([x, y]) => x * 1048576 + y));
      const solid = (x, y) => x < 0 || y < 0 || x >= n || y >= n || here.has(x * 1048576 + y);
      level = level.filter(([x, y]) => solid(x - 1, y) && solid(x + 1, y) && solid(x, y - 1) && solid(x, y + 1));
    }
    return total >= n;
  };
  let hi = 1;
  while (!fits(hi)) hi *= 2;
  let lo = Math.floor(hi / 2) + 1;
  if (hi === 1) lo = 1;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (fits(mid)) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

