function generate(rand, size) {
  if (size === 'small') {
    // Values near the pyramid totals 1, 4, 10, 20, 35, 56 are the interesting ones.
    if (rand() < 0.4) {
      const k = 1 + Math.floor(rand() * 6);
      return [Math.max(1, k * (k + 1) * (k + 2) / 6 + Math.floor(rand() * 3) - 1)];
    }
    return [1 + Math.floor(rand() * 60)];
  }
  if (rand() < 0.5) return [100000000 + Math.floor(rand() * 900000001)];
  const k = 1000 + Math.floor(rand() * 817);
  return [Math.min(1000000000, k * (k + 1) * (k + 2) / 6 + Math.floor(rand() * 3) - 1)];
}
